referenceSolutions.javascript:
export function palindromePartitions(text) {
  const n = text.length;
  const palindrome = Array.from({ length: n }, () => Array(n).fill(false));
  for (let left = n - 1; left >= 0; left--) {
    for (let right = left; right < n; right++) {
      palindrome[left][right] = text[left] === text[right]
        && (right - left < 2 || palindrome[left + 1][right - 1]);
    }
  }
  const result = [];
  const path = [];
  function visit(start) {
    if (start === n) {
      result.push([...path]);
      return;
    }
    for (let end = start; end < n; end++) {
      if (!palindrome[start][end]) continue;
      path.push(text.slice(start, end + 1));
      visit(end + 1);
      path.pop();
    }
  }
  visit(0);
  return result;
}

